  randomBytes,
} = require('node:crypto');

randomBytes(256, (err, buf) => {
  if (err) throw err;
  console.log(`${buf.length} bytes of random data: ${buf.toString('hex')}`);
});copy
```

If the `callback` function is not provided, the random bytes are generated synchronously and returned as a [`Buffer`](https://nodejs.org/docs/latest/api/buffer.html). An error will be thrown if there is a problem generating the bytes.
```
