#### Custom inspection functions on objects 
History Version | Changes  
---|---  
v17.3.0, v16.14.0 | The inspect argument is added for more interoperability.  
v0.1.97 | Added in: v0.1.97  
Objects may also define their own [`[util.inspect.custom](depth, opts, inspect)`](https://nodejs.org/docs/latest/api/util.html#utilinspectcustom) function, which `util.inspect()` will invoke and use the result of when inspecting the object.
```
import { inspect } from 'node:util';

class Box {
  constructor(value) {
    this.value = value;
  }

  [inspect.custom](depth, options, inspect) {
    if (depth < 0) {
      return options.stylize('[Box]', 'special');
    }

    const newOptions = Object.assign({}, options, {
      depth: options.depth === null ? null : options.depth - 1,
    });

    // Five space padding because that's the size of "Box< ".
    const padding = ' '.repeat(5);
    const inner = inspect(this.value, newOptions)
                  .replace(/\n/g, `\n${padding}`);
    return `${options.stylize('Box', 'special')}< ${inner} >`;
  }
}

const box = new Box(true);

console.log(inspect(box));
// "Box< true >"const { inspect } = require('node:util');

